     5  /* check if a line is a code fence; return the
     6   * end of the code fence. if passed, width of
     7   * the fence rule and character will be returned */
     8  static size_t
     9  is_codefence(uint8_t *data, size_t size, size_t *width, uint8_t *chr)
    10  {
    11          size_t i = 0, n = 1;
    12          uint8_t c;
    13
    14          /* skipping initial spaces */
    15          if (size < 3)
    16                  return 0;
    17
    18          if (data[0] == ' ') { i++;
    19          if (data[1] == ' ') { i++;
    20          if (data[2] == ' ') { i++; } } }
    21
    22          /* looking at the hrule uint8_t */
    23          c = data[i];
    24          if (i + 2 >= size || !(c=='~' || c=='`'))
    25                  return 0;
    26
    27          /* the fence must be that same character */
    28          while (++i < size && data[i] == c)
    29                  ++n;
    30
    31          if (n < 3)
    32                  return 0;
    33
    34          if (width) *width = n;
    35          if (chr) *chr = c;
    36          return i;
    37  }
