    78  /* is_atxheader • returns whether the line is a hash-prefixed header */
    79  static int
    80  is_atxheader(hoedown_document *doc, uint8_t *data, size_t size)
    81  {
    82          size_t level = 0, begin = 0, len;
    83          uint8_t *p;
    84
    85          if (data[0] != '#')
    86                  return 0;
    87
    88          while (level < size && level < 6 && data[level] == '#')
    89                  level++;
    90
    91          if (level >= size || data[level] == '\n') {
    92                          return 0;
    93          }
    94
    95          len = size - level;
    96          p = memchr(data + level, '\n', len);
    97          if (p) {
    98                  len = p - (data + level) + 1;
    99          }
   100
   101          /* if the header is only whitespace, it is not a header */
   102          if (len && is_empty_all(data + level, len)) {
   103                  return 0;
   104          }
   105
   106          if ((doc->ext_flags & HOEDOWN_EXT_SPACE_HEADERS) && level < size && data[level] != ' ') {
   107                  return 0;
   108          }
   109
   110          /* if the header is only special attribute, it is not a header */
   111          if (len && (doc->ext_flags & HOEDOWN_EXT_SPECIAL_ATTRIBUTE)) {
   112                  p = memchr(data + level, '{', len);
   113                  if (p) {
   114                          /* get number of characters from # to { */
   115                          begin = p - (data + level);
   116                          if (begin > 0 && !is_empty_all(data + level, begin)) {
   117                                  return 1;
   118                          }
   119                          /* check for special attributes after the # */
   120                          return !parse_inline_attributes(data + level + begin, len - begin, NULL, doc->attr_activation);
   121                  }
   122          }
   123
   124          return 1;
   125  }
