   127  /* is_headerline • returns whether the line is a setext-style hdr underline */
   128  static int
   129  is_headerline(uint8_t *data, size_t size)
   130  {
   131          size_t i = 0;
   132
   133          /* test of level 1 header */
   134          if (data[i] == '=') {
   135                  for (i = 1; i < size && data[i] == '='; i++);
   136                  while (i < size && data[i] == ' ') i++;
   137                  return (i >= size || data[i] == '\n') ? 1 : 0; }
   138
   139          /* test of level 2 header */
   140          if (data[i] == '-') {
   141                  for (i = 1; i < size && data[i] == '-'; i++);
   142                  while (i < size && data[i] == ' ') i++;
   143                  return (i >= size || data[i] == '\n') ? 2 : 0; }
   144
   145          return 0;
   146  }
