   424                          parse_attributes(work.data, work.size, NULL, attr, "paragraph", 9, 1, doc->attr_activation);
   425                          if (attr->size > 0) {
   426                                  /* remove the length of the attribute from the work size - the 12 comes
   427                                  * from the leading space (1), the paragraph (9), the @ symbol (1), and
   428                                  * the {} (2) (any extra spaces in the attribute are included inside
   429                                  * the attribute) */
   430                                  work.size -= attr->size + 12;
   431                          }
   432                  }
   433
   434                  hoedown_buffer *tmp = newbuf(doc, BUFFER_BLOCK);
   435                  parse_inline(tmp, doc, work.data, work.size);
   436                  if (doc->md.paragraph)
   437                          doc->md.paragraph(ob, tmp, attr, &doc->data);
   438                  popbuf(doc, BUFFER_BLOCK);
   439                  popbuf(doc, BUFFER_ATTRIBUTE);
   440          } else {
   441                  hoedown_buffer *header_work;
   442                  hoedown_buffer *attr_work;
   443                  size_t len;
   444
   445                  if (work.size) {
   446                          size_t beg;
   447                          i = work.size;
   448                          work.size -= 1;
   449
   450                          while (work.size && data[work.size] != '\n')
   451                                  work.size -= 1;
   452
   453                          beg = work.size + 1;
   454                          while (work.size && data[work.size - 1] == '\n')
   455                                  work.size -= 1;
   456
   457                          if (work.size > 0) {
   458                                  hoedown_buffer *tmp = newbuf(doc, BUFFER_BLOCK);
   459                                  parse_inline(tmp, doc, work.data, work.size);
   460
   461                                  if (doc->md.paragraph)
   462                                          doc->md.paragraph(ob, tmp, NULL, &doc->data);
   463
   464                                  popbuf(doc, BUFFER_BLOCK);
   465                                  work.data += beg;
   466                                  work.size = i - beg;
   467                          }
   468                          else work.size = i;
   469                  }
   470
   471                  header_work = newbuf(doc, BUFFER_SPAN);
   472                  attr_work = newbuf(doc, BUFFER_ATTRIBUTE);
   473
   474                  len = work.size;
   475                  if (doc->ext_flags & HOEDOWN_EXT_SPECIAL_ATTRIBUTE) {
   476                          len = parse_attributes(work.data, work.size, attr_work, NULL, "", 0, 1, doc->attr_activation);
   477                  }
