   494  /* parse_fencedcode • handles parsing of a block-level code fragment */
   495  static size_t
   496  parse_fencedcode(hoedown_buffer *ob, hoedown_document *doc, uint8_t *data, size_t size, unsigned int flags)
   497  {
   498          hoedown_buffer text = { 0, 0, 0, 0, NULL, NULL, NULL };
   499          hoedown_buffer lang = { 0, 0, 0, 0, NULL, NULL, NULL };
   500          size_t i = 0, text_start, line_start;
   501          size_t w, w2;
   502          size_t width, width2;
   503          uint8_t chr, chr2;
   504          /* needed for parse_attribute functions as buffer functions do not work with
   505           * buffers on the stack */
   506          hoedown_buffer *attr = newbuf(doc, BUFFER_ATTRIBUTE);
   507
   508
   509          /* parse codefence line */
   510          while (i < size && data[i] != '\n')
   511                  i++;
   512
   513          w = parse_codefence(doc, data, i, &lang, &width, &chr, flags, attr);
   514          if (!w) {
   515                  popbuf(doc, BUFFER_ATTRIBUTE);
   516                  return 0;
   517          }
   518
   519          /* search for end */
   520          i++;
   521          text_start = i;
   522          while ((line_start = i) < size) {
   523                  while (i < size && data[i] != '\n')
   524                          i++;
   525
   526                  w2 = is_codefence(data + line_start, i - line_start, &width2, &chr2);
   527                  if (w == w2 && width == width2 && chr == chr2 &&
   528                          is_empty(data + (line_start+w), i - (line_start+w)))
   529                          break;
   530
   531                  if (i < size) i++;
   532          }
   533
   534          text.data = data + text_start;
   535          text.size = line_start - text_start;
   536
   537          if (doc->md.blockcode) {
   538                  doc->fencedcode_char = chr;
   539                  doc->md.blockcode(ob, text.size ? &text : NULL, lang.size ? &lang : NULL, attr->size ? attr : NULL, &doc->data);
   540                  doc->fencedcode_char = 0;
   541          }
   542
   543          popbuf(doc, BUFFER_ATTRIBUTE);
   544
